// ChessMate personalization controls: move color and compact YouTube playback.
try {
  N.arrowColor = '#83d6f1';
  chrome.storage?.local?.get({arrowColor:'#83d6f1'}).then(v => { N.arrowColor = /^#[0-9a-f]{6}$/i.test(v.arrowColor) ? v.arrowColor : '#83d6f1'; });
  chrome.storage?.onChanged?.addListener((changes, area) => {
    if (area === 'local' && changes.arrowColor) {
      N.arrowColor = /^#[0-9a-f]{6}$/i.test(changes.arrowColor.newValue) ? changes.arrowColor.newValue : '#83d6f1';
      if (W?.lastArrow) W.showArrow(W.lastArrow.uci, W.lastArrow.evaluation, W.lastArrow.depth);
    }
  });
  const cmShowArrow = N.prototype.showArrow;
  N.prototype.showArrow = function(...args) {
    const result = cmShowArrow.apply(this, args);
    const color = N.arrowColor || '#83d6f1';
    this.svg?.querySelectorAll('[stroke="#83d6f1"], [fill="#83d6f1"]').forEach(el => {
      if (el.getAttribute('stroke') === '#83d6f1') el.setAttribute('stroke', color);
      if (el.getAttribute('fill') === '#83d6f1') el.setAttribute('fill', color);
    });
    return result;
  };
  const cmRenderModes = ge.prototype.renderModesTab;
  ge.prototype.renderModesTab = function(el) {
    cmRenderModes.call(this, el);
    const color = N.arrowColor || '#83d6f1';
    const box = document.createElement('section');
    box.className = 'cm-arrow-color-control';
    box.innerHTML = '<label for="cm-arrow-color">Màu đường chỉ</label><input id="cm-arrow-color" type="color" aria-label="Chọn màu đường chỉ"><span>Áp dụng ngay trên bàn cờ</span>';
    box.querySelector('input').value = color;
    box.querySelector('input').addEventListener('input', ev => chrome.storage.local.set({arrowColor:ev.target.value}));
    el.append(box);
    if (!document.getElementById('cm-arrow-color-style')) {
      const style = document.createElement('style'); style.id = 'cm-arrow-color-style';
      style.textContent = '#chessmate-hud-root .cm-arrow-color-control{display:flex;align-items:center;gap:9px;padding:11px;margin-top:10px;border:1px solid rgba(131,214,241,.2);border-radius:10px;background:rgba(20,43,58,.72);font:600 11px system-ui;color:#e1f4fb}#chessmate-hud-root .cm-arrow-color-control input{width:34px;height:30px;padding:2px;border:1px solid rgba(255,255,255,.18);border-radius:7px;background:transparent;cursor:pointer}#chessmate-hud-root .cm-arrow-color-control span{margin-left:auto;color:#91aeb9;font-size:9px}';
      document.head.append(style);
    }
  };
  const cmRenderMusic = ge.prototype.renderMusicTab;
  ge.prototype.renderMusicTab = function(el) {
    cmRenderMusic.call(this, el);
    const dock = this.root.querySelector('#cm-music-dock');
    const attach = () => {
      const iframe = dock?.querySelector('iframe');
      const head = el.querySelector('.cm-music-heading');
      if (!iframe || !head || head.querySelector('#cm-music-visual-toggle')) return;
      const button = document.createElement('button'); button.id = 'cm-music-visual-toggle'; button.type = 'button';
      button.textContent = iframe.dataset.cmHidden === '1' ? 'HIỆN VIDEO' : 'ẨN VIDEO';
      button.style.cssText = 'margin-left:6px;padding:6px 8px;border:1px solid rgba(131,214,241,.25);border-radius:8px;background:#102536;color:#c7efff;font-size:9px;font-weight:800;cursor:pointer';
      button.onclick = () => {
        const hidden = iframe.dataset.cmHidden !== '1'; iframe.dataset.cmHidden = hidden ? '1' : '0';
        iframe.style.opacity = hidden ? '0' : '1'; iframe.style.pointerEvents = hidden ? 'none' : 'auto';
        iframe.style.position = hidden ? 'absolute' : 'static'; iframe.style.left = hidden ? '0' : '';
        iframe.style.top = hidden ? '0' : ''; iframe.style.width = '200px'; iframe.style.height = '200px';
        iframe.style.zIndex = hidden ? '-1' : 'auto'; dock.style.position = 'relative';
        dock.style.height = hidden ? '34px' : ''; dock.style.minHeight = hidden ? '34px' : '';
        button.textContent = hidden ? 'HIỆN VIDEO' : 'ẨN VIDEO';
      };
      head.append(button);
    };
    attach();
    if (dock && dock.dataset.cmWatch !== '1') {
      dock.dataset.cmWatch = '1';
      new MutationObserver(attach).observe(dock, {childList:true,subtree:true});
    }
  };
} catch (error) { console.info('[ChessMate] Personalization controls unavailable:', error); }
